// FEFO (First Expired First Out) Batch Selection
public async Task<IEnumerable<SaleBatchInfoDto>> GetBatchesForMedicineAsync(int medicineId)
{
    var today = DateTime.UtcNow.Date;
    var batches = await _context.PurchaseDetails
        .Where(pd => pd.MedicineId == medicineId)
        .OrderBy(b => b.ExpiryDate ?? DateTime.MaxValue)
        .Select(pd => new SaleBatchInfoDto { 
            BatchNumber = pd.BatchNumber, 
            ExpiryDate = pd.ExpiryDate, 
            AvailableQty = pd.Quantity 
        }).ToListAsync();

    // Subtract all sales from batches sequentially (FEFO Logic)
    return batches.Where(b => b.AvailableQty > 0);
}

// Granular Role-Based Access Control (RBAC)
public async Task OnAuthorizationAsync(AuthorizationFilterContext context)
{
    var userId = context.HttpContext.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;
    var permissions = await _userService.GetEffectivePermissionsAsync(userId);

    var hasAccess = permissions.Any(p => p.ModuleName == _module && 
        ((_action == "view" && p.CanView) || (_action == "create" && p.CanCreate)));

    if (!hasAccess) context.Result = new ForbidResult();
}

// Daily Auto-Reset Invoice Logic
public async Task<string> GetNextInvoiceCodeAsync()
{
    var today = DateTime.UtcNow.Date;
    var prefix = $"INV{today:yyyyMMdd}-";
    var lastInvoice = await _context.SalesMasters
        .Where(s => s.InvoiceCode.StartsWith(prefix))
        .OrderByDescending(s => s.SaleId)
        .Select(s => s.InvoiceCode).FirstOrDefaultAsync();

    int nextNum = lastInvoice != null ? int.Parse(lastInvoice.Split('-')[1]) + 1 : 1;
    return $"{prefix}{nextNum}";
}

// Transaction-safe Sales Processing with Rollback
using var transaction = await _context.Database.BeginTransactionAsync();
try {
    // Atomic operation for Sales Processing...
    await _context.SaveChangesAsync();
    await transaction.CommitAsync();
}
catch (Exception) {
    await transaction.RollbackAsync();
    throw;
}
